Fetching Yearly Dividends
To get yearly dividends for a stock, we make use of the quantmod package which interfaces with various sources online to fetch stock data. Here’s the code chunk to pull yearly dividends:

library(quantmod)
library(dplyr)

get_yearly_dividends &lt;- function(ticker, years) {
  historical_dividends &lt;- quantmod::getDividends(
    Symbol = ticker,
    from = paste0(min(years), "-01-01"),
    to = paste0(max(years), "-12-31")
  ) |&gt;
    setNames("dividends")

  yearly_data &lt;- historical_dividends |&gt;
    dplyr::as_tibble(rownames = "date") |&gt;
    dplyr::mutate(
      ticker = gsub(".SA", "", ticker),
      year = lubridate::year(date)
    ) |&gt;
    group_by(year) |&gt;
    dplyr::summarise(
      dividends = sum(dividends)
    )

  return(yearly_data)
}

# Example for Coca-Cola Co.
get_yearly_dividends("KO", c(2020:2023))

# A tibble: 4 × 2
   year dividends
  &lt;dbl&gt;     &lt;dbl&gt;
1  2020      1.64
2  2021      1.68
3  2022      1.76
4  2023      1.38

Getting Yearly Closing Price
While dividends tell half the story, to evaluate the attractiveness of the dividends, we need to know at what price the stock closed at the end of each year. Here’s how we can fetch that data:

get_yearly_closing_price &lt;- function(ticker, years) {
  historical_prices &lt;- quantmod::getSymbols(
    Symbol = ticker,
    from = paste0(min(years), "-01-01"),
    to = paste0(max(years), "-12-31"),
    auto.assign = FALSE
  ) |&gt;
    dplyr::as_tibble(rownames = "date") |&gt;
    dplyr::select(date, tidyr::contains("Adjusted")) |&gt;
    setNames(c("date", "price")) |&gt;
    dplyr::mutate(
      ticker = gsub(".SA", "", ticker),
      year = lubridate::year(date)
    ) |&gt;
    group_by(year) |&gt;
    dplyr::summarise(
      price = last(price)
    )
  return(historical_prices)
}

# Example for Coca-Cola Co.
get_yearly_closing_price("KO", c(2020:2023))

# A tibble: 4 × 2
   year price
  &lt;dbl&gt; &lt;dbl&gt;
1  2020  50.5
2  2021  56.2
3  2022  62.2
4  2023  52.5

Calculating Yearly Yield
Combining the dividends and the closing price, we can calculate the yield for the stock year-over-year:

get_yearly_yield &lt;- function(ticker, years) {
  yearly_yields &lt;- get_yearly_dividends(ticker, years) |&gt;
    dplyr::left_join(
      get_yearly_closing_price(ticker, years),
      by = "year"
    ) |&gt;
    dplyr::mutate(
      ticker = gsub(".SA", "", ticker),
      yield = round(100 * dividends / price, 4)
    )

  return(yearly_yields)
}

# Example for Coca-Cola Co.
get_yearly_yield("KO", c(2020:2023))

# A tibble: 4 × 5
   year dividends price ticker yield
  &lt;dbl&gt;     &lt;dbl&gt; &lt;dbl&gt; &lt;chr&gt;  &lt;dbl&gt;
1  2020      1.64  50.5 KO      3.25
2  2021      1.68  56.2 KO      2.99
3  2022      1.76  62.2 KO      2.83
4  2023      1.38  52.5 KO      2.63

Valuation by Country and Industry
After reading the data I have created two charts to briefly show the summarized data by Country and by Industry.
In this part I also create the color palettes that will be used in other charts as well.
Here comes a nice tip: the usage of the R package MetBrewer to create very nice color palettes.


Code
create_color_palette &lt;- function(vector, theme) {
  dplyr::tibble(
    name = vector,
    itemStyle = dplyr::tibble(
      color = as.character(MetBrewer::met.brewer(theme, length(vector)))
    )
  )
}

unicorn_data_by_country &lt;- unicorn_data |&gt;
  dplyr::group_by(Country) |&gt;
  dplyr::summarise(`Valuation ($B)` = sum(`Valuation ($B)`)) |&gt;
  dplyr::arrange(dplyr::desc(`Valuation ($B)`)) |&gt;
  head(15)

colors_country &lt;- create_color_palette(unicorn_data_by_country$Country, "Derain")

unicorn_data_by_industry &lt;- unicorn_data |&gt;
  dplyr::group_by(Industry) |&gt;
  dplyr::summarise(`Valuation ($B)` = sum(`Valuation ($B)`)) |&gt;
  dplyr::arrange(dplyr::desc(`Valuation ($B)`))

colors_industry &lt;- create_color_palette(unicorn_data_by_industry$Industry, "Juarez")


Below we can see the sum of all the companies’ Valuations for Industry and Country in a column chart.


Code
unicorn_data_by_industry |&gt;
  dplyr::left_join(
    colors_industry |&gt; dplyr::rename(Industry = name, color = `itemStyle`),
    by = "Industry"
  ) |&gt;
  echarts4r::e_charts(`Valuation ($B)`) |&gt;
  echarts4r::e_legend(show = FALSE) |&gt;
  echarts4r::e_bar(Industry) |&gt;
  echarts4r::e_y_axis(type = "category") |&gt;
  echarts4r::e_grid(containLabel = TRUE) |&gt;
  echarts4r::e_tooltip() |&gt;
  echarts4r::e_add_nested('itemStyle', color) |&gt;
  echarts4r::e_title(text = "Unicorns by Industry", subtext = "Sum the valuation of all the Industries")








